import {$,api,esc,icon,field,errorHTML,formSubmit} from './ui.js';
import {safeReturn,authURL} from './auth-routing.js';
const audience=document.body.dataset.audience,register=audience==='user'&&document.body.dataset.mode==='register',admin=audience==='admin';
const destination=safeReturn(audience,new URLSearchParams(location.search).get('return'));
const brand=`<span class="auth-brand-mark">${icon('camera')}</span>探索与拍摄`;
$('#auth-root').innerHTML=`<main class="auth-layout ${admin?'console-auth':''}"><section class="auth-story"><a class="auth-brand" href="${admin?'/login.html':'/#discover'}">${brand}${admin?'<span class="auth-brand-suffix">管理工作台</span>':''}</a><div class="auth-story-photo"><img src="/shared/${admin?'nmu-building.jpg':'nmu-campus.jpg'}" alt="北方民族大学校园参考照片"><div class="auth-story-caption"><span>北方民族大学 · 校园探索计划</span><h1>${admin?'每一个发现，<br>都值得认真对待。':'走过的日常，<br>值得再看一眼。'}</h1><p>${admin?'维护点位、连接探索者，<br>一起记录校园的变化。':'从一个校园角落开始，<br>留下属于自己的照片和手记。'}</p></div><small class="auth-photo-credit">校园参考配图 · 国家民委 / 北方民族大学</small></div><div class="auth-story-footer"><span>${admin?'校园管理':'校园探索'}</span><span>银川 · 北方民族大学</span></div></section><section class="auth-form-side"><div class="auth-topline">${admin?'<span>管理员专属入口</span>':`<a href="${esc(destination)}">← 返回校园</a>`}<span>探索与拍摄</span></div><div class="auth-form-card"><p class="auth-kicker">${admin?'管理工作台':register?'加入校园探索':'欢迎回来'}</p><h2>${register?'从这里，开始探索。':admin?'登录管理工作台':'继续你的校园发现。'}</h2><p class="auth-description">${admin?'请使用超级管理员为你创建的账号。':register?'当前为邀请内测，填写有效邀请码即可加入。':'登录后，收藏喜欢的角落，继续未完的小路。'}</p>${admin?'':`<nav class="auth-switch" aria-label="登录方式"><a href="${esc(authURL(audience,'login',destination))}" class="${!register?'active':''}">账号登录</a><a href="${esc(authURL(audience,'register',destination))}" class="${register?'active':''}">邀请码注册</a></nav>`}<form id="auth-form">${field(admin?'管理员账号':'账号','username','text','','required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+" autocomplete="username" placeholder="字母、数字或下划线"')}${register?field('昵称','nickname','text','','required maxlength="24" autocomplete="nickname" placeholder="大家怎么称呼你"'):''}<div class="auth-password-field">${field('密码','password','password','','required minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'" placeholder="至少 8 位"')}<button type="button" id="password-visibility" aria-label="显示密码">显示</button></div>${register?field('确认密码','confirm','password','','required minlength="8" maxlength="128" autocomplete="new-password" placeholder="再次输入密码"')+field('邀请码','inviteCode','text','','required minlength="6" maxlength="30" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="填写管理员提供的邀请码"'):''}${errorHTML}<button class="button wide auth-submit" type="submit">${register?'注册并进入校园':admin?'进入工作台':'登录'}<span aria-hidden="true">↗</span></button></form><p class="auth-footnote">${admin?'管理员账号不开放自行注册。':'校园探索、拍摄与手记，按自己的节奏来。'}</p></div><footer class="auth-footer">北方民族大学校园探索与拍摄 · 试点项目</footer></section></main>`;
$('#password-visibility').onclick=()=>{const input=$('[name=password]'),visible=input.type==='password';input.type=visible?'text':'password';$('#password-visibility').textContent=visible?'隐藏':'显示';$('#password-visibility').setAttribute('aria-label',visible?'隐藏密码':'显示密码');};
$('#auth-form').onsubmit=e=>formSubmit(e,async f=>{
 if(register&&f.password!==f.confirm)throw Error('两次密码输入不一致');
 await api('/api/auth/'+(register?'register':'login'),'POST',f);
 location.replace(destination);
});
api('/api/auth/me').then(me=>{if(me.account)location.replace(destination);}).catch(()=>{});
